window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ac975ac6fee20ef5"]={"versions": [{"id": "FIG-ac975ac6fee20ef5", "releases": ["R1.5.1", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Netzwerk- und Hardware-Architekturdiagramm für Ethernet-basierte Zeitsynchronisation gemäß AUTOSAR PRS TimeSyncProtocol. Dargestellt ist eine „Time Aware Bridge with GTM not as Management CPU“, bestehend aus einer kombinierten Bridge-/TimeSlave-Einheit mit integriertem Switch und separater Host-CPU sowie angebundenen externen Ethernet-Knoten (Global Time Master und TimeSlaves).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>TimeSlave / Bridge</strong>: Übergeordnete logische Einheit, die eine Management CPU und einen Switch umfasst.</li>\n<li><strong>Management CPU</strong>: Host-Prozessor zur Steuerung der Bridge.</li>\n<li><strong>Switch</strong>: Ethernet-Switch mit nummerierten Ports 1 bis 4 sowie weiteren Ports (...).</li>\n<li><strong>Interne Schnittstellen</strong>:</li>\n<li><code>MII</code>: Media Independent Interface zwischen Management CPU und Port 1 des Switches zur Datenkommunikation.</li>\n<li><code>SPI</code>: Serial Peripheral Interface zwischen Management CPU und Switch zur Konfiguration und Registersteuerung.</li>\n<li><strong>Externe Knoten</strong>:</li>\n<li><strong>GTM</strong> (Global Time Master): Externer Zeitgeberknoten, über Ethernet (<code>ETH</code>) an Port 3 des Switches angebunden.</li>\n<li><strong>TimeSlave</strong> (links): Externer Zeitempfänger, über <code>ETH</code> an Port 2 angebunden.</li>\n<li><strong>TimeSlave</strong> (rechts): Externer Zeitempfänger, über <code>ETH</code> an Port 4 angebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine statische Topologie ohne eingezeichnete Nachrichtenflüsse oder Zeitstempel-Messpunkte. Die physikalische Topologie etabliert Ethernet-Verbindungen (<code>ETH</code>) zwischen den Switch-Ports 2, 3, 4 und den jeweiligen externen Knoten (TimeSlaves, GTM) sowie eine interne Host-Kopplung (MII, SPI) an Port 1.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild veranschaulicht das architektonische Deployment-Szenario, bei dem der Global Time Master (GTM) nicht auf der Management CPU der Time-Aware Bridge lokalisiert ist, sondern als eigenständiges Steuergerät über einen Switch-Port (Port 3) angebunden wird. Entwickler müssen berücksichtigen, dass die Bridge die Synchronisationsnachrichten (Sync, Follow_Up) des GTM über den Switch weiterleiten und die Residence Time kompensieren muss, während die lokale Management CPU über MII/SPI angebunden ist.</p>"}, {"id": "FIG-18f1a0c554addc12", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Messpunktdiagramm für Ethernet-basierte Zeitmessung (Pdelay) gemäß AUTOSAR PRS TimeSyncProtocol. Dargestellt ist eine Time-Aware Bridge mit Switch und Management CPU sowie die Zuordnung von Zeitstempel-Messpunkten (T1, T3, T4, T7, T8) bei Ausführung des Peer-to-Peer Propagation Delay Measurement (Pdelay) mit einem externen Global Time Master (GTM) und einem externen TimeSlave.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>TimeSlave / Bridge</strong>: Übergeordneter Bridge-Knoten.</li>\n<li><strong>Management CPU</strong>: Lokaler Controller der Bridge, angebunden an Switch-Port 1.</li>\n<li><strong>Switch</strong>: Ethernet-Switch mit durchnummerierten Ports 1, 2, 3, 4, ...</li>\n<li><strong>Externe Knoten</strong>:</li>\n<li><strong>GTM</strong>: Global Time Master, über Link an Port 3 angebunden.</li>\n<li><strong>TimeSlave</strong> (links): Aktiver externer Zeitempfänger, an Port 2 angebunden.</li>\n<li><strong>TimeSlave</strong> (rechts): Inaktiver bzw. nicht an der Pdelay-Messung beteiligter Knoten (ausgegraut).</li>\n<li><strong>Messpunkte</strong>:</li>\n<li><code>T1</code>: Zeitstempel-Messpunkt an der internen Schnittstelle zwischen Management CPU und Switch-Port 1.</li>\n<li><code>T3</code>, <code>T4</code>: Zeitstempel-Messpunkte am Ethernet-Link zwischen Switch-Port 3 und dem GTM.</li>\n<li><code>T7</code>, <code>T8</code>: Zeitstempel-Messpunkte an den Switch-Ein-/Austrittspunkten in Richtung des linken TimeSlave (Port 2).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert die bidirektionalen Pdelay-Messpfade (grün gestrichelte Linien mit Richtungspfeilen):</p>\n<ul class=\"fig-list\">\n<li>Pdelay-Signalisierung zwischen Management CPU und Port 1 unter Erfassung des Zeitstempels <code>T1</code>.</li>\n<li>Pdelay-Signalisierung zwischen Switch-Port 3 und dem externen GTM unter Erfassung der Zeitstempel <code>T3</code> und <code>T4</code>.</li>\n<li>Pdelay-Signalisierung zwischen Switch-Port 2 und dem externen linken TimeSlave unter Erfassung der Zeitstempel <code>T7</code> und <code>T8</code>.</li>\n</ul>\n<p class=\"fig-p\">Der rechte TimeSlave ist ausgegraut und nimmt an diesem dargestellten Messablauf nicht teil.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient Entwicklern zur normativen Lokalisierung der Pdelay-Messpunkte (<code>T1</code>, <code>T3</code>, <code>T4</code>, <code>T7</code>, <code>T8</code>) für die Port-zu-Port-Laufzeitmessung und Residence-Time-Bestimmung bei Time-Aware Bridges, bei denen der GTM als separater Knoten an Port 3 betrieben wird. Es definiert die Erfassungspunkte für Ingress- und Egress-Zeitstempel zur Laufzeitkompensation gemäß IEEE 802.1AS.</p>"}], "trans": [{"from": "FIG-ac975ac6fee20ef5", "to": "FIG-18f1a0c554addc12", "fr": "R1.5.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung des dynamischen Pdelay-Messflusses (grün gestrichelte Pfeile) zwischen Management CPU, Switch-Ports und externen Knoten.</li>\n<li>Ergänzung von Zeitstempel-Messpunkten: T1 an der Verbindung zwischen Management CPU und Port 1, T3 und T4 am Link zwischen Port 3 und GTM, sowie T7 und T8 am Switch-Eintritt/-Austritt in Richtung des linken TimeSlave.</li>\n<li>Ergänzung einer Legende für „Pdelay“ (grüne gestrichelte Linie mit Pfeil).</li>\n<li>Ausgrauen des rechten TimeSlave-Knotens und seiner Anbindungsleitung.</li>\n<li>Wegfall der Schnittstellenbeschriftungen „MII“, „SPI“ und der externen Busbeschriftungen „ETH“.</li>\n</ul>"}, {"from": "FIG-18f1a0c554addc12", "to": "FIG-ac975ac6fee20ef5", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Entfernung des Pdelay-Messflusses inklusive aller Richtungspfeile und der Legende („Pdelay“).</li>\n<li>Entfernung sämtlicher Zeitstempel-Messpunkte (T1, T3, T4, T7, T8).</li>\n<li>Wiedereinsetzen der expliziten Schnittstellenbezeichnungen („MII“, „SPI“, „ETH“).</li>\n<li>Vollständige Aktivierung/Hervorhebung des rechten TimeSlave-Knotens (zuvor ausgegraut) mit violetter Füllung und durchgezogener ETH-Verbindungslinie von Port 4.</li>\n</ul>"}]};
